export class ApiLabIndexPage extends Page {
  declare props: ApiLabIndexPageProps;
  declare state: ApiLabIndexPageState;
  _searchDebounce: ReturnType<typeof setTimeout> | null = null;

  initialState(): ApiLabIndexPageState {
    return { query: '', page: 1, pageSize: PAGE_SIZE };
  }

  /** 根据搜索词过滤 LABS（命中 title / desc / tags 任一即保留） */
  _filtered(): Lab[] {
    const q = this.state.query.trim().toLowerCase();
    if (!q) return LABS;
    return LABS.filter((lab: any) => {
      if (lab.title.toLowerCase().includes(q)) return true;
      if (lab.desc.toLowerCase().includes(q)) return true;
      if (lab.tags.some((t: any) => t.toLowerCase().includes(q))) return true;
      return false;
    });
  }

  componentWillUnmount(): void {
    // 清理搜索防抖定时器，避免卸载后 setState
    if (this._searchDebounce) clearTimeout(this._searchDebounce);
  }

  renderPage(): Node | string | (Node | string)[] {
    const filtered = this._filtered();
    const totalPages = Math.max(1, Math.ceil(filtered.length / this.state.pageSize));
    // 搜索/分页变化后页码可能越界，夹取一下
    const page = Math.min(this.state.page, totalPages);
    const start = (page - 1) * this.state.pageSize;
    const pageItems = filtered.slice(start, start + this.state.pageSize);

    // 搜索框：受控但延迟过滤——直接操作 DOM 显示，keyup 时再 setState 触发重渲染
    const searchInput = h('input', {
      type: 'search',
      class: 'input',
      placeholder: '搜索 API 名称、描述或标签…',
      'aria-label': '搜索 API 实验室',
      value: this.state.query,
      onInput: (e: Event) => {
        // 防抖：连续输入时只在停顿 200ms 后过滤，避免每键重建 12 张卡片+数百 Tag 节点。
        // 输入框本身不受控——value 由浏览器维护，setState 只用于重建卡片列表。
        const value = (e.target as HTMLInputElement).value;
        const selStart = (e.target as HTMLInputElement).selectionStart;
        const selEnd = (e.target as HTMLInputElement).selectionEnd;
        if (this._searchDebounce) clearTimeout(this._searchDebounce);
        this._searchDebounce = setTimeout(() => {
          this.setState({ query: value, page: 1 });
          // setState 会重建 input（受控值需同步），焦点会丢——恢复到输入时的光标位置（而非强制末尾）
          requestAnimationFrame(() => {
            const newInput = this.$<HTMLInputElement>('input[type="search"]');
            if (newInput) {
              newInput.focus();
              newInput.setSelectionRange(selStart, selEnd);
            }
          });
        }, 200);
      },
    });

    const pagination = new Pagination({
      total: filtered.length,
      current: page,
      pageSize: this.state.pageSize,
      showTotal: true,
      showSizeChanger: true,
      showQuickJumper: true,
      onChange: (nextPage: number, nextSize: number) => {
        this.setState({ page: nextPage, pageSize: nextSize });
        // 切页后滚动到列表顶部
        requestAnimationFrame(() => (this.$('.feature-grid') as any)?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
      },
    });
    this.registerChild(pagination);

    return [
      h('h2', { class: 'section-title' }, 'API 实验室'),
      h('p', { class: 'text-secondary mb-lg' },
        '借鉴 MDN Web Docs 的组织形式，每一类 API 都配有可交互的实验室。点击卡片进入对应模块。'),

      // 搜索栏
      h('div', { class: 'flex items-center gap-sm mb-lg', style: { maxWidth: '480px' } },
        searchInput,
        h('span', { class: 'fs-sm text-tertiary' },
          filtered.length === LABS.length
            ? `共 ${LABS.length} 个`
            : `${filtered.length} / ${LABS.length} 个匹配`),
      ),

      h('div', { class: 'feature-grid' },
        ...pageItems.map((lab: any) => {
          const card = new Card({
            title: h('div', { class: 'flex items-center gap-sm' },
              h('span', { class: 'feature-card__icon', 'aria-hidden': 'true' }, lab.icon),
              h('span', {}, lab.title),
            ),
            hoverable: true,
            children: [
              h('p', { class: 'feature-card__desc' }, lab.desc),
              h('div', { class: 'feature-card__meta' },
                ...lab.tags.map((t: any) => h(Tag, { color: 'primary' }, t)),
              ),
            ],
          });
          this.registerChild(card);
          const node = card.render() as HTMLElement;
          node.classList.add('feature-card');
          node.setAttribute('role', 'button');
          node.setAttribute('tabindex', '0');
          node.setAttribute('aria-label', `进入 ${lab.title} 实验室`);
          node.addEventListener('click', () => this.props.router.push(lab.path));
          node.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              this.props.router.push(lab.path);
            }
          });
          return node;
        }),
      ),

      // 无结果提示
      pageItems.length === 0 ? h('div', { class: 'card' },
        h('div', { class: 'card__body', style: { textAlign: 'center', padding: '32px' } },
          h('p', { class: 'text-tertiary' }, '没有匹配的 API，换个关键词试试？'),
        ),
      ) : '',

      // 分页
      filtered.length > 0 ? h('div', { class: 'mt-lg', style: { display: 'flex', justifyContent: 'center' } },
        pagination.render(),
      ) : '',
    ];
  }
}
